begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1);
create function pg_temp.assert_hr(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'HRGA assertion: %',msg;end if;end $$;
create function pg_temp.deny_hr(statement text,msg text) returns void language plpgsql as $$begin begin execute statement;exception when others then return;end;raise exception 'Expected denial: %',msg;end $$;
insert into public.branches(code,name) values('HRQ','[CONTOH] HRGA other branch');
insert into auth.users(id,email) select ('ad100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'hrga.qa.'||i||'@example.invalid' from generate_series(1,4)i;
insert into public.employee_directory(id,branch_code,full_name,npp) select ('ad200000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=4 then 'HRQ' else 'DPS' end,'[CONTOH] HRGA QA '||i,'0099'||i from generate_series(1,4)i;
insert into public.profiles(id,employee_id,branch_code,full_name,is_active) select ('ad100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('ad200000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=4 then 'HRQ' else 'DPS' end,'[CONTOH] HRGA QA account '||i,true from generate_series(1,4)i;
insert into public.user_role_assignments(profile_id,branch_code,role_code,grant_reason) select ('ad100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=4 then 'HRQ' else 'DPS' end,(array['hrga','inspector','equipment_manager','hrga'])[i],'[CONTOH] Transaction-only HRGA regression' from generate_series(1,4)i;
insert into public.certificate_types(id,branch_code,code,name,category) values('ad300000-0000-4000-8000-000000000001','DPS','CONTOH_HRQA','[CONTOH] HRGA QA license','personnel');
insert into public.personnel_certificates(id,branch_code,employee_id,certificate_type_id,original_title,certificate_number,issue_date,expiry_date) values('ad400000-0000-4000-8000-000000000001','DPS','ad200000-0000-4000-8000-000000000002','ad300000-0000-4000-8000-000000000001','[CONTOH] License','[CONTOH] OLD','2024-01-01','2025-01-01');
select set_config('request.jwt.claim.sub','ad100000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.assert_hr(private.actor_enabled(),'unknown inactive directory flag does not block an approved account');
select pg_temp.deny_hr($q$update public.employee_directory set employment_status='inactive' where id='ad200000-0000-4000-8000-000000000002'$q$,'reason and date required');
select pg_temp.deny_hr($q$update public.employee_directory set employment_status='inactive',employment_status_reason='resigned',employment_status_note='[CONTOH] future date rejected',employment_status_effective_on='2999-01-01' where id='ad200000-0000-4000-8000-000000000002'$q$,'future date rejected');
select pg_temp.deny_hr($q$update public.employee_directory set employment_status='inactive',employment_status_reason='resigned',employment_status_note='[CONTOH] own status rejected',employment_status_effective_on=current_date where id='ad200000-0000-4000-8000-000000000001'$q$,'self status change rejected');
update public.employee_directory set employment_status='inactive',employment_status_reason='resigned',employment_status_note='[CONTOH] reviewed resignation',employment_status_effective_on=current_date where id='ad200000-0000-4000-8000-000000000002' and employment_status_version=0;
select pg_temp.assert_hr((select count(*)=1 from public.employee_status_events where employee_id='ad200000-0000-4000-8000-000000000002'),'history appended once');
select pg_temp.assert_hr((select npp='00992' from public.employee_directory where id='ad200000-0000-4000-8000-000000000002'),'NPP kept as text');
select pg_temp.assert_hr((select count(*)=1 from public.personnel_certificates where employee_id='ad200000-0000-4000-8000-000000000002'),'certificate retained');
select pg_temp.deny_hr($q$insert into public.personnel_renewal_cases(branch_code,certificate_id,notes) values('DPS','ad400000-0000-4000-8000-000000000001','[CONTOH] inactive blocked')$q$,'inactive holder renewal blocked');
select set_config('request.jwt.claim.sub','ad100000-0000-4000-8000-000000000002',true);
select pg_temp.assert_hr(not private.actor_enabled(),'already issued JWT loses application access');
select pg_temp.assert_hr(not exists(select 1 from public.user_role_assignments),'role grants hidden from inactive actor');
select set_config('request.jwt.claim.sub','ad100000-0000-4000-8000-000000000001',true);
update public.employee_directory set employment_status='active',employment_status_reason='reactivated',employment_status_note='[CONTOH] approved return',employment_status_effective_on=current_date where id='ad200000-0000-4000-8000-000000000002' and employment_status_version=1;
update public.employee_directory set employment_status='inactive',employment_status_reason='other',employment_status_note='[CONTOH] stale update must not save',employment_status_effective_on=current_date where id='ad200000-0000-4000-8000-000000000002' and employment_status_version=1;
select pg_temp.assert_hr((select employment_status='active' and employment_status_version=2 from public.employee_directory where id='ad200000-0000-4000-8000-000000000002'),'optimistic version rejects stale changes');
insert into public.personnel_renewal_cases(id,branch_code,certificate_id,notes) values('ad500000-0000-4000-8000-000000000001','DPS','ad400000-0000-4000-8000-000000000001','[CONTOH] Start HRGA renewal');
update public.personnel_renewal_cases set status='processing',notes='[CONTOH] Applying for replacement' where id='ad500000-0000-4000-8000-000000000001';
select pg_temp.deny_hr($q$select public.complete_personnel_renewal('ad500000-0000-4000-8000-000000000001',2,'{"certificate_number":"[CONTOH] NO PROOF","issue_date":"2026-01-01","expiry_date":"2027-01-01","interval_months":12}'::jsonb,'[CONTOH] Must fail without evidence')$q$,'atomic completion needs evidence');
select pg_temp.deny_hr($q$select public.complete_personnel_renewal('ad500000-0000-4000-8000-000000000001',1,'{"certificate_number":"[CONTOH] STALE","issue_date":"2026-01-01","expiry_date":"2027-01-01","source_folder_url":"https://drive.google.com/drive/folders/CONTOH-HRQA"}'::jsonb,'[CONTOH] Stale completion')$q$,'stale completion');
select pg_temp.deny_hr($q$select public.complete_personnel_renewal('ad500000-0000-4000-8000-000000000001',2,'{"certificate_number":"[CONTOH] ROLLBACK","issue_date":"2026-01-01","expiry_date":"2027-01-01","source_folder_url":"https://drive.google.com/drive/folders/CONTOH-HRQA"}'::jsonb,'x')$q$,'failed case update rolls back inserted certificate');
select pg_temp.assert_hr((select count(*)=1 from public.personnel_certificates where employee_id='ad200000-0000-4000-8000-000000000002'),'failed completions leave no partial certificate');
select public.complete_personnel_renewal('ad500000-0000-4000-8000-000000000001',2,'{"certificate_number":"[CONTOH] NEW","issue_date":"2026-01-01","expiry_date":"2027-01-01","interval_months":12,"source_folder_url":"https://drive.google.com/drive/folders/CONTOH-HRQA"}'::jsonb,'[CONTOH] New certificate checked');
select pg_temp.assert_hr((select status='renewed' and replacement_certificate_id is not null from public.personnel_renewal_cases where id='ad500000-0000-4000-8000-000000000001'),'case finished with new certificate');
select pg_temp.assert_hr((select issue_date='2024-01-01' and expiry_date='2025-01-01' from public.personnel_certificates where id='ad400000-0000-4000-8000-000000000001'),'old dates preserved');
select set_config('request.jwt.claim.sub','ad100000-0000-4000-8000-000000000003',true);
update public.employee_directory set employment_status='inactive',employment_status_reason='other',employment_status_note='[CONTOH] unauthorized PTK change',employment_status_effective_on=current_date where id='ad200000-0000-4000-8000-000000000002';
select pg_temp.assert_hr((select employment_status='active' from public.employee_directory where id='ad200000-0000-4000-8000-000000000002'),'PTK cannot change employment status');
select pg_temp.assert_hr(not exists(select 1 from public.employee_status_events),'PTK cannot read HRGA notes');
select set_config('request.jwt.claim.sub','ad100000-0000-4000-8000-000000000004',true);
select pg_temp.assert_hr(not exists(select 1 from public.employee_status_events where branch_code='DPS'),'HRGA cross branch isolation');
select pg_temp.assert_hr(not has_table_privilege('authenticated','public.employee_status_events','UPDATE') and not has_table_privilege('authenticated','public.employee_status_events','INSERT'),'append-only history');
reset role;
select pass('HRGA lifecycle, reasons, dates, immutable history, JWT denial, scope and atomic certificate replacement');
select * from finish();
rollback;
